package net.local.picocapture;

import android.os.Bundle;import android.content.*;import android.content.res.ColorStateList;import android.graphics.*;import android.graphics.drawable.*;import android.text.TextUtils;import android.view.*;import android.widget.*;

/** Reference-inspired dark two-column UI, hosted by Pico in the dock. */
public class FloatingActivity extends MainActivity {
    static final int BG=0xff1e1e1e,CARD=0xff292929,FIELD=0xff323232,BLUE=0xff3e8bff,TEXT=0xfff4f4f4,MUTED=0xffaaaaaa;
    TextView link;LinearLayout customSize,advancedBox;
    @Override protected void attachBaseContext(Context base){android.content.res.Configuration ui=new android.content.res.Configuration();ui.densityDpi=240;super.attachBaseContext(base.createConfigurationContext(ui));}
    final android.os.Handler uiHandler=new android.os.Handler();
    final Runnable update=new Runnable(){public void run(){String s=CaptureService.status;int cut=s.indexOf("\nVLC / OBS:");if(cut>=0)s=s.substring(0,cut);s=s.replace("/sdcard/Movies/PicoCapture/","");if(s.startsWith("Ready."))s="Ready to capture\nChoose your quality, then press Start.";status.setText(s);link.setText(CaptureService.streamUrl.isEmpty()?"Start streaming to show your link":CaptureService.streamUrl);uiHandler.postDelayed(this,1000);}};
    public void onCreate(Bundle b){super.onCreate(b);getWindow().setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));getWindow().getDecorView().setSystemUiVisibility(5894);
        LinearLayout panel=column();panel.setPadding(dp(26),dp(20),dp(26),dp(20));panel.setBackground(shape(BG,28));setContentView(panel);
        LinearLayout header=row();header.setGravity(Gravity.CENTER_VERTICAL);panel.addView(header,new LinearLayout.LayoutParams(-1,dp(48)));
        TextView icon=text("◉",30,Color.WHITE);icon.setGravity(Gravity.CENTER);icon.setBackground(shape(BLUE,12));header.addView(icon,new LinearLayout.LayoutParams(dp(44),dp(44)));
        TextView title=text("Pico Capture",26,TEXT);LinearLayout.LayoutParams tl=new LinearLayout.LayoutParams(0,-2,1);tl.leftMargin=dp(14);header.addView(title,tl);TextView badge=text("v"+BuildConfig.VERSION_NAME+" · DOCK",11,MUTED);badge.setPadding(dp(12),0,dp(12),0);header.addView(badge);Button hide=button("Hide",FIELD);header.addView(hide,new LinearLayout.LayoutParams(dp(80),dp(42)));hide.setOnClickListener(v->finish());
        TextView intro=text("Record locally, stream over Wi-Fi, or do both. Choose your output quality below.",14,MUTED);intro.setPadding(dp(14),dp(10),dp(14),dp(10));intro.setBackground(shape(CARD,12));LinearLayout.LayoutParams il=new LinearLayout.LayoutParams(-1,-2);il.topMargin=dp(12);il.bottomMargin=dp(14);panel.addView(intro,il);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout columns=row();columns.setGravity(Gravity.TOP);scroll.addView(columns,new ScrollView.LayoutParams(-1,-2));LinearLayout left=column(),right=column();LinearLayout.LayoutParams ll=new LinearLayout.LayoutParams(0,-2,1);ll.rightMargin=dp(24);columns.addView(left,ll);columns.addView(right,new LinearLayout.LayoutParams(0,-2,1));
        section(left,"Capture quality");LinearLayout quality=row();left.addView(quality);resolution=spinner(weighted(quality,true),"Resolution",new String[]{"720p","1080p","1440p","4K","Custom"});resolution.setSelection(1);rate=spinner(weighted(quality,false),"Frame rate",new String[]{"30 FPS","60 FPS","72 FPS","90 FPS","120 FPS","Custom"});rate.setSelection(1);
        customSize=row();left.addView(customSize);width=number(weighted(customSize,true),"Width",1920);height=number(weighted(customSize,false),"Height",1080);customSize.setVisibility(View.GONE);fps=number(left,"Custom FPS",60);final View fpsLabel=left.getChildAt(left.getChildCount()-2);fps.setVisibility(View.GONE);fpsLabel.setVisibility(View.GONE);
        upscaler=spinner(left,"GPU upscale / enhance",new String[]{"Off · original capture","Smooth · fast scaling","Bicubic · finer edges","Sharp · fast + sharpen","SGSR 1 · balanced","SGSR 1 · fine edges"});
        LinearLayout scaling=column();left.addView(scaling);sourceScale=spinner(scaling,"Capture size relative to output",new String[]{"50% · 540p → 1080p","67% · 720p → 1080p","75% · 810p → 1080p","100% · same size"});sourceScale.setSelection(1);sharpness=number(scaling,"Sharpness · 0–100 (Sharp mode)",35);add(scaling,text("Examples above use 1080p output. Applies to recording and every stream. SGSR combines scaling and adaptive sharpening. Fine edges is stronger. Spatial filtering; no AI or generated frames.",12,MUTED),-2,8);scaling.setVisibility(View.GONE);
        upscaler.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){scaling.setVisibility(i==0?View.GONE:View.VISIBLE);sharpness.setEnabled(i==3);}});
        bitrate=number(left,"Video bitrate · Mbps",12);encoder=spinner(left,"Video encoder",names.toArray(new String[0]));for(int i=0;i<names.size();i++)if(names.get(i).startsWith("OMX.qcom.video.encoder.avc")){encoder.setSelection(i);break;}
        Button caps=button("Encoder capabilities",FIELD);add(left,caps,dp(42),10);caps.setOnClickListener(v->showCapabilities());Button expand=button("Advanced options  ▾",FIELD);add(left,expand,dp(42),10);advancedBox=column();left.addView(advancedBox);advancedBox.setVisibility(View.GONE);expand.setOnClickListener(v->{boolean show=advancedBox.getVisibility()!=View.VISIBLE;advancedBox.setVisibility(show?View.VISIBLE:View.GONE);expand.setText(show?"Advanced options  ▴":"Advanced options  ▾");});
        nativeCadence=new CheckBox(this);nativeCadence.setText("90 Hz capture workaround · restores on Stop");nativeCadence.setTextColor(TEXT);nativeCadence.setButtonTintList(ColorStateList.valueOf(BLUE));nativeCadence.setChecked(true);advancedBox.addView(nativeCadence);
        browserCompatibility=new CheckBox(this);browserCompatibility.setText("Browser compatibility encoder · non-AVC uses extra GPU/VPU work");browserCompatibility.setTextColor(TEXT);browserCompatibility.setButtonTintList(ColorStateList.valueOf(BLUE));browserCompatibility.setChecked(true);advancedBox.addView(browserCompatibility);
        Button licenses=button("SGSR license",FIELD);add(advancedBox,licenses,dp(42),10);licenses.setOnClickListener(v->{try(java.io.InputStream in=getAssets().open("SGSR-LICENSE.txt")){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] bfr=new byte[2048];int n;while((n=in.read(bfr))>0)bytes.write(bfr,0,n);error(bytes.toString("UTF-8"));}catch(Exception e){error(e.toString());}});
        port=number(advancedBox,"Wi-Fi HTTP port",8088);rtspPort=number(advancedBox,"RTSP TCP port · 0 disables",8554);label(advancedBox,"UDP MPEG-TS destination · optional PC IP:port");udpDestination=new EditText(this);input(udpDestination);udpDestination.setHint("192.168.0.2:9000");advancedBox.addView(udpDestination);label(advancedBox,"Encoder options · JSON");advanced=new EditText(this);input(advanced);advanced.setText("{}");advanced.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);advanced.setSingleLine(false);advanced.setMinLines(2);advancedBox.addView(advanced,new LinearLayout.LayoutParams(-1,-2));add(advancedBox,text("Example: {\"bitrate-mode\":2,\"i-frame-interval\":1}",12,MUTED),-2,8);
        section(right,"Output & session");mode=spinner(right,"Save / share",new String[]{"Record + stream","Record only","Stream only"});audio=new CheckBox(this);audio.setText("Internal audio");audio.setTextColor(TEXT);audio.setTextSize(16);audio.setButtonTintList(ColorStateList.valueOf(BLUE));audio.setMinHeight(dp(48));right.addView(audio);
        LinearLayout live=column();live.setPadding(dp(16),dp(14),dp(16),dp(14));live.setBackground(shape(CARD,16));add(right,live,-2,8);live.addView(text("Browser live link",13,MUTED));link=text("Start streaming to show your link",18,TEXT);link.setTextIsSelectable(true);add(live,link,-2,8);Button copy=button("Copy browser link",FIELD);add(live,copy,dp(44),10);copy.setOnClickListener(v->copy());status=text("Ready to capture",14,MUTED);status.setTextIsSelectable(true);status.setPadding(0,dp(12),0,0);live.addView(status);
        Button logs=button("Session log",FIELD);add(right,logs,dp(42),12);logs.setOnClickListener(v->{try{String s=new String(java.nio.file.Files.readAllBytes(new java.io.File(getFilesDir(),"root.log").toPath()));error(s.length()>14000?s.substring(s.length()-14000):s);}catch(Exception e){error(e.toString());}});add(right,text("Measured FPS reflects Pico's source cadence. 120 FPS requests currently deliver about 72 FPS.",12,MUTED),-2,12);
        LinearLayout actions=row();LinearLayout.LayoutParams al=new LinearLayout.LayoutParams(-1,dp(54));al.topMargin=dp(14);panel.addView(actions,al);Button start=button("Start capture",BLUE),stop=button("Stop & restore",FIELD);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(0,-1,1);ap.rightMargin=dp(12);actions.addView(start,ap);actions.addView(stop,new LinearLayout.LayoutParams(0,-1,1));start.setOnClickListener(v->startCapture());stop.setOnClickListener(v->startService(new Intent(this,CaptureService.class).setAction("STOP")));
        resolution.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){customSize.setVisibility(i==4?View.VISIBLE:View.GONE);int[][] sizes={{1280,720},{1920,1080},{2560,1440},{3840,2160}};if(i<4){width.setText(""+sizes[i][0]);height.setText(""+sizes[i][1]);}}});
        rate.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){fps.setVisibility(i==5?View.VISIBLE:View.GONE);fpsLabel.setVisibility(i==5?View.VISIBLE:View.GONE);if(i<5)fps.setText(new String[]{"30","60","72","90","120"}[i]);}});
        restoreChoices();
        if(getIntent().getBooleanExtra("preview",false))panel.postDelayed(()->{try{Bitmap image=Bitmap.createBitmap(panel.getWidth(),panel.getHeight(),Bitmap.Config.ARGB_8888);panel.draw(new Canvas(image));try(java.io.FileOutputStream f=new java.io.FileOutputStream(new java.io.File(getFilesDir(),"ui-preview.png"))){image.compress(Bitmap.CompressFormat.PNG,100,f);}image.recycle();}catch(Exception e){android.util.Log.e("PicoCapture","Preview failed",e);}},1500);
    }
    int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
    LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}LinearLayout row(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.HORIZONTAL);return v;}
    LinearLayout weighted(LinearLayout parent,boolean gap){LinearLayout c=column();LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);if(gap)p.rightMargin=dp(12);parent.addView(c,p);return c;}
    GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
    void add(LinearLayout p,View v,int height,int margin){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,height);lp.topMargin=dp(margin);p.addView(v,lp);}
    void section(LinearLayout p,String s){TextView t=text(s,17,TEXT);t.setTypeface(null,Typeface.BOLD);p.addView(t);}
    @Override void label(LinearLayout p,String s){TextView t=text(s,13,MUTED);t.setPadding(0,dp(12),0,dp(6));p.addView(t);}
    void input(EditText e){e.setTextColor(TEXT);e.setHintTextColor(MUTED);e.setTextSize(17);e.setPadding(dp(14),dp(8),dp(14),dp(8));e.setBackground(shape(FIELD,12));e.setSingleLine(true);}
    @Override EditText number(LinearLayout p,String s,int n){label(p,s);EditText e=new EditText(this);input(e);e.setInputType(2);e.setText(""+n);p.addView(e,new LinearLayout.LayoutParams(-1,dp(48)));return e;}
    Button button(String s,int color){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(16);b.setTextColor(TEXT);b.setMinHeight(0);b.setMinimumHeight(0);b.setPadding(dp(12),0,dp(12),0);b.setBackground(new RippleDrawable(ColorStateList.valueOf(0x44ffffff),shape(color,12),null));return b;}
    @Override Spinner spinner(LinearLayout p,String s,String[] values){label(p,s);Spinner v=new Spinner(this,Spinner.MODE_DROPDOWN);v.setBackground(shape(FIELD,12));v.setPopupBackgroundDrawable(shape(0xff3d3d3d,12));v.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values){public View getView(int pos,View old,ViewGroup parent){TextView t=text(getItem(pos)+"  ▾",15,TEXT);t.setGravity(Gravity.CENTER_VERTICAL);t.setPadding(dp(14),0,dp(10),0);t.setSingleLine(true);t.setEllipsize(TextUtils.TruncateAt.MIDDLE);return t;}public View getDropDownView(int pos,View old,ViewGroup parent){TextView t=text(getItem(pos),15,TEXT);t.setPadding(dp(16),dp(14),dp(16),dp(14));return t;}});p.addView(v,new LinearLayout.LayoutParams(-1,dp(50)));return v;}
    void copy(){String url=CaptureService.streamUrl;if(url.isEmpty()){Toast.makeText(this,"Start a streaming session first",Toast.LENGTH_SHORT).show();return;}((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Pico stream",url));Toast.makeText(this,"Link copied",Toast.LENGTH_SHORT).show();}
    @Override protected void onResume(){super.onResume();handler.removeCallbacks(refresh);uiHandler.post(update);}
    @Override protected void onPause(){uiHandler.removeCallbacks(update);super.onPause();}
}
